app.MapControllers();
app.Urls.Add("http://127.0.0.1:5000");
await app.StartAsync();

var client = new HttpClient() { BaseAddress = new Uri("http://127.0.0.1:5000") };
Console.WriteLine("Result for /class");
await PrintResult(await SendRequest("class"));
Console.WriteLine();

Console.WriteLine("Result for /record");
await PrintResult(await SendRequest("record"));
